// Fixed-capacity MOSS-TTS-Nano runner. Neural sessions are fail-closed in QNN mode;
// KV slot copies, token orchestration, channel averaging, and WAV encoding remain CPU work.
#include <algorithm>
#include <array>
#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <memory>
#include <sstream>
#include <stdexcept>
#include <string>
#include <thread>
#include <unordered_map>
#include <unordered_set>
#include <vector>
#include "generated_contract.h"
#include "onnxruntime_cxx_api.h"
using Clock=std::chrono::steady_clock;using namespace moss_contract;
namespace {
struct Args{std::string mode,root,out,result,setup_log,profiles,backend,profiling="detailed";int runs=4;};
Args Parse(int n,char**v){Args a;auto take=[&](int&i){if(++i>=n)throw std::runtime_error("missing value");return std::string(v[i]);};for(int i=1;i<n;++i){std::string k=v[i];if(k=="--mode")a.mode=take(i);else if(k=="--model-root")a.root=take(i);else if(k=="--output")a.out=take(i);else if(k=="--result-json")a.result=take(i);else if(k=="--setup-log")a.setup_log=take(i);else if(k=="--profile-dir")a.profiles=take(i);else if(k=="--backend")a.backend=take(i);else if(k=="--profiling")a.profiling=take(i);else if(k=="--runs")a.runs=std::stoi(take(i));else throw std::runtime_error("unknown "+k);}if((a.mode!="qnn"&&a.mode!="cpu")||(a.profiling!="off"&&a.profiling!="detailed")||a.root.empty()||a.out.empty()||a.result.empty()||a.setup_log.empty()||a.profiles.empty()||a.runs<1||(a.mode=="qnn"&&a.backend.empty()))throw std::runtime_error("invalid args");return a;}
double Sec(Clock::time_point t){return std::chrono::duration<double>(Clock::now()-t).count();}
long StatusValue(const char*key){std::ifstream f("/proc/self/status");std::string line;while(std::getline(f,line))if(line.rfind(key,0)==0){std::istringstream s(line.substr(std::string(key).size()));long v=-1;s>>v;return v;}return -1;}
long PssKb(){std::ifstream f("/proc/self/smaps_rollup");std::string line;while(std::getline(f,line))if(line.rfind("Pss:",0)==0){std::istringstream s(line.substr(4));long v=-1;s>>v;return v;}return -1;}
struct Sampler{std::atomic<bool>stop{false};std::thread t;long peak_rss=0,peak_pss=0,min_threads=1L<<30,max_threads=0,samples=0;Sampler(){t=std::thread([&]{int p=0;while(!stop){peak_rss=std::max(peak_rss,StatusValue("VmRSS:"));long th=StatusValue("Threads:");if(th>=0){min_threads=std::min(min_threads,th);max_threads=std::max(max_threads,th);}if(p++%10==0)peak_pss=std::max(peak_pss,PssKb());++samples;std::this_thread::sleep_for(std::chrono::milliseconds(50));}});}~Sampler(){stop=true;if(t.joinable())t.join();}};
struct JavaRandom{uint64_t s;explicit JavaRandom(uint64_t seed):s((seed^0x5DEECE66DULL)&((1ULL<<48)-1)){}uint64_t Next(int bits){s=(s*0x5DEECE66DULL+0xBULL)&((1ULL<<48)-1);return s>>(48-bits);}double U(){return double((Next(26)<<27)+Next(27))/double(1ULL<<53);}};
Ort::SessionOptions Opt(const std::string&p,const Args&a){Ort::SessionOptions o;o.SetIntraOpNumThreads(1);o.SetInterOpNumThreads(1);o.SetExecutionMode(ExecutionMode::ORT_SEQUENTIAL);o.SetGraphOptimizationLevel(GraphOptimizationLevel::ORT_ENABLE_ALL);if(a.profiling!="off")o.EnableProfiling(p.c_str());if(a.mode=="qnn"){o.AddConfigEntry("session.disable_cpu_ep_fallback","1");std::unordered_map<std::string,std::string>x={{"backend_path",a.backend},{"offload_graph_io_quantization","0"}};if(a.profiling!="off"){x["profiling_level"]="detailed";x["profiling_file_path"]=p+".qnn.csv";}o.AppendExecutionProvider("QNN",x);}return o;}
struct TS{std::unique_ptr<Ort::Session>s;double setup;std::string prefix;};
TS Make(Ort::Env&e,const std::string&m,const std::string&p,const Args&a){auto o=Opt(p,a);auto t=Clock::now();auto s=std::make_unique<Ort::Session>(e,m.c_str(),o);return{std::move(s),Sec(t),p};}
template<class T>Ort::Value Tensor(std::vector<T>&v,const std::vector<int64_t>&shape,Ort::MemoryInfo&m,size_t count=0){if(!count)count=v.size();return Ort::Value::CreateTensor<T>(m,v.data(),count,shape.data(),shape.size());}
std::vector<std::string> PrefillOut(){std::vector<std::string>x={"global_hidden"};for(int i=0;i<12;++i){x.push_back("present_key_"+std::to_string(i));x.push_back("present_value_"+std::to_string(i));}return x;}
std::vector<std::string> DecodeIn(){std::vector<std::string>x;for(int i=0;i<12;++i){x.push_back("past_key_"+std::to_string(i));x.push_back("past_value_"+std::to_string(i));}return x;}
std::vector<const char*> Ptrs(const std::vector<std::string>&x){std::vector<const char*>p;for(auto&s:x)p.push_back(s.c_str());return p;}
void Put16(std::ofstream&s,uint16_t v){char b[2]={char(v),char(v>>8)};s.write(b,2);}void Put32(std::ofstream&s,uint32_t v){char b[4]={char(v),char(v>>8),char(v>>16),char(v>>24)};s.write(b,4);}
void Wav(const std::string&p,const std::vector<float>&a){std::ofstream s(p,std::ios::binary|std::ios::trunc);uint32_t n=a.size()*2;s.write("RIFF",4);Put32(s,36+n);s.write("WAVEfmt ",8);Put32(s,16);Put16(s,1);Put16(s,1);Put32(s,kSampleRate);Put32(s,kSampleRate*2);Put16(s,2);Put16(s,16);s.write("data",4);Put32(s,n);for(float x:a){x=std::max(-1.f,std::min(1.f,x));int q=int(x*32767.f);Put16(s,uint16_t(int16_t(q)));}if(!s)throw std::runtime_error("wav write");}
struct Metric{double total=0,prefill=0,local=0,decode=0,codec=0,wav=0,first_audio=0;int frames=0,samples=0;double rms=0,peak=0;};
struct Route{TS&pre,&dec,&loc,&codec;Ort::MemoryInfo&mem;};
Metric Synthesize(Route&r,const std::string&wav){Metric z;auto all=Clock::now();
 std::vector<int32_t>ids(kPrefillIds.begin(),kPrefillIds.end()),mask(kPrefillLength,1);auto ti=Tensor(ids,{1,kPrefillLength,kRowWidth},r.mem),tm=Tensor(mask,{1,kPrefillLength},r.mem);std::vector<const char*>in={"input_ids","attention_mask"};std::vector<Ort::Value>iv;iv.push_back(std::move(ti));iv.push_back(std::move(tm));auto pon=PrefillOut();auto po=Ptrs(pon);auto t=Clock::now();auto pr=r.pre.s->Run(Ort::RunOptions{nullptr},in.data(),iv.data(),2,po.data(),po.size());z.prefill=Sec(t);
 std::vector<float>hidden(768);const float*gh=pr[0].GetTensorData<float>();std::copy(gh+(kPrefillLength-1)*768,gh+kPrefillLength*768,hidden.begin());std::array<std::vector<float>,24>state;constexpr size_t plane=12*64;for(int j=0;j<24;++j){state[j].assign(kDecodeStateCapacity*plane,0);const float*x=pr[j+1].GetTensorData<float>();std::copy(x,x+kPrefillLength*plane,state[j].begin());}pr.clear();
 JavaRandom random(kSeed);std::array<std::unordered_set<int32_t>,16>seen;std::vector<int32_t>codes;auto din=DecodeIn();auto don=PrefillOut();auto dp=Ptrs(don);
 for(int step=0;step<kMaxFrames;++step){std::vector<int32_t>sm(16*kCodebookSize,0);for(int q=0;q<16;++q)for(int x:seen[q])if(x>=0&&x<kCodebookSize)sm[q*kCodebookSize+x]=1;std::vector<float>au={float(std::clamp(random.U(),1e-6,1.-1e-6))},ru(16);for(float&x:ru)x=float(std::clamp(random.U(),1e-6,1.-1e-6));std::vector<Ort::Value>lv;lv.push_back(Tensor(hidden,{1,768},r.mem));lv.push_back(Tensor(sm,{1,16,1024},r.mem));lv.push_back(Tensor(au,{1},r.mem));lv.push_back(Tensor(ru,{1,16},r.mem));std::vector<const char*>ln={"global_hidden","repetition_seen_mask","assistant_random_u","audio_random_u"},lo={"should_continue","frame_token_ids"};t=Clock::now();auto lr=r.loc.s->Run(Ort::RunOptions{nullptr},ln.data(),lv.data(),4,lo.data(),2);z.local+=Sec(t);const int32_t*cont=lr[0].GetTensorData<int32_t>();if(*cont<=0)break;const int32_t*frame=lr[1].GetTensorData<int32_t>();std::vector<int32_t>row(17,kAudioPad);row[0]=kAssistantSlot;for(int q=0;q<16;++q){row[q+1]=frame[q];codes.push_back(frame[q]);seen[q].insert(frame[q]);}lr.clear();int32_t valid=kPrefillLength+step;std::vector<int32_t>vl={valid};std::vector<Ort::Value>dv;dv.push_back(Tensor(row,{1,1,17},r.mem));dv.push_back(Tensor(vl,{1},r.mem));for(int j=0;j<24;++j)dv.push_back(Tensor(state[j],{1,kDecodeInputCapacity,12,64},r.mem,kDecodeInputCapacity*plane));std::vector<const char*>dn={"input_ids","past_valid_lengths"};auto dip=Ptrs(din);dn.insert(dn.end(),dip.begin(),dip.end());t=Clock::now();auto dr=r.dec.s->Run(Ort::RunOptions{nullptr},dn.data(),dv.data(),dv.size(),dp.data(),dp.size());z.decode+=Sec(t);const float*nh=dr[0].GetTensorData<float>();std::copy(nh,nh+768,hidden.begin());for(int j=0;j<24;++j){const float*x=dr[j+1].GetTensorData<float>()+kDecodeInputCapacity*plane;std::copy(x,x+plane,state[j].begin()+valid*plane);}++z.frames;
 }
 if(z.frames<=0)throw std::runtime_error("no frames");std::vector<int32_t>padded(kMaxFrames*16,0);std::copy(codes.begin(),codes.end(),padded.begin());std::vector<int32_t>length={z.frames};std::vector<Ort::Value>cv;cv.push_back(Tensor(padded,{1,kMaxFrames,16},r.mem));cv.push_back(Tensor(length,{1},r.mem));std::vector<const char*>cn={"audio_codes","audio_code_lengths"},co={"audio","audio_lengths"};t=Clock::now();auto cr=r.codec.s->Run(Ort::RunOptions{nullptr},cn.data(),cv.data(),2,co.data(),2);z.codec=Sec(t);z.first_audio=Sec(all);const int32_t*reported=cr[1].GetTensorData<int32_t>();z.samples=*reported;if(z.samples<=0||z.samples>kMaxFrames*3840)throw std::runtime_error("audio length");const float*a=cr[0].GetTensorData<float>();std::vector<float>mono(z.samples);double sq=0;for(int i=0;i<z.samples;++i){float x=(a[i]+a[kMaxFrames*3840+i])*.5f;mono[i]=x;sq+=double(x)*x;z.peak=std::max(z.peak,double(std::abs(x)));}z.rms=std::sqrt(sq/z.samples);t=Clock::now();Wav(wav,mono);z.wav=Sec(t);z.total=Sec(all);return z;}
}
int main(int argc,char**argv){try{Args a=Parse(argc,argv);std::filesystem::create_directories(a.profiles);Sampler sampler;Ort::Env env(ORT_LOGGING_LEVEL_INFO,"moss-fixed-e2e");auto root=std::filesystem::path(a.root);std::ofstream setup_out(a.setup_log,std::ios::trunc);if(!setup_out)throw std::runtime_error("setup log open");setup_out<<"component\tseconds\n";auto all=Clock::now();TS pre=Make(env,(root/"prefill.onnx").string(),a.profiles+"/prefill",a);setup_out<<"prefill\t"<<pre.setup<<"\n"<<std::flush;TS dec=Make(env,(root/"decode.onnx").string(),a.profiles+"/decode",a);setup_out<<"decode\t"<<dec.setup<<"\n"<<std::flush;TS loc=Make(env,(root/"local.onnx").string(),a.profiles+"/local",a);setup_out<<"local\t"<<loc.setup<<"\n"<<std::flush;TS codec=Make(env,(root/"codec.onnx").string(),a.profiles+"/codec",a);setup_out<<"codec\t"<<codec.setup<<"\n"<<std::flush;double setup=Sec(all);long rss_sessions=StatusValue("VmRSS:");auto mem=Ort::MemoryInfo::CreateCpu(OrtArenaAllocator,OrtMemTypeDefault);Route route{pre,dec,loc,codec,mem};std::vector<Metric>m;for(int i=0;i<a.runs;++i)m.push_back(Synthesize(route,a.out));Ort::AllocatorWithDefaultOptions alloc;std::vector<std::string>profiles;if(a.profiling!="off")for(TS*x:{&pre,&dec,&loc,&codec})profiles.push_back(x->s->EndProfilingAllocated(alloc).get());sampler.stop=true;if(sampler.t.joinable())sampler.t.join();long hwm=StatusValue("VmHWM:");std::ofstream result(a.result,std::ios::trunc);if(!result)throw std::runtime_error("result json open");auto&os=result;os<<"{\n  \"result\": \"passed\",\n  \"mode\": \""<<a.mode<<"\",\n  \"profiling\": \""<<a.profiling<<"\",\n  \"setup_seconds\": "<<setup<<",\n  \"session_setup_seconds\": {\"prefill\": "<<pre.setup<<", \"decode\": "<<dec.setup<<", \"local\": "<<loc.setup<<", \"codec\": "<<codec.setup<<"},\n  \"rss_after_sessions_kib\": "<<rss_sessions<<",\n  \"peak_vm_hwm_kib\": "<<hwm<<",\n  \"peak_sampled_rss_kib\": "<<sampler.peak_rss<<",\n  \"peak_sampled_pss_kib\": "<<sampler.peak_pss<<",\n  \"process_threads_min\": "<<sampler.min_threads<<",\n  \"process_threads_max\": "<<sampler.max_threads<<",\n  \"samples\": "<<sampler.samples<<",\n  \"first_audio_semantics\": \"run start through complete fixed-capacity codec decode; first PCM exists in memory; non-streaming\",\n  \"cpu_orchestration\": [\"fixed KV slot extraction/copy\",\"token/repetition/random orchestration\",\"stereo-to-mono averaging\",\"PCM16 WAV encoding\"],\n  \"runs\": [\n";for(size_t i=0;i<m.size();++i){auto&x=m[i];double dur=double(x.samples)/kSampleRate,rtf=x.total/dur;os<<"    {\"index\": "<<i<<", \"frames\": "<<x.frames<<", \"samples\": "<<x.samples<<", \"audio_seconds\": "<<dur<<", \"total_seconds\": "<<x.total<<", \"rtf\": "<<rtf<<", \"first_audio_seconds\": "<<x.first_audio<<", \"prefill_seconds\": "<<x.prefill<<", \"decode_seconds\": "<<x.decode<<", \"local_seconds\": "<<x.local<<", \"codec_seconds\": "<<x.codec<<", \"wav_seconds\": "<<x.wav<<", \"rms\": "<<x.rms<<", \"peak\": "<<x.peak<<"}"<<(i+1<m.size()?",":"")<<"\n";}os<<"  ],\n  \"profile_paths\": [";for(size_t i=0;i<profiles.size();++i)os<<(i?", ":"")<<"\""<<profiles[i]<<"\"";os<<"]\n}\n";if(!result)throw std::runtime_error("result json write");return 0;}catch(const Ort::Exception&e){std::cerr<<"ORT "<<e.GetOrtErrorCode()<<": "<<e.what()<<"\n";return 2;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<"\n";return 3;}}
